def bold(msg) :
    return termcolor.colored(msg, 'blue', attrs=['bold']) 

def hr(margin=20):
    display(HTML(f'<hr style="margin: {margin}px 0;">'))

def print_test(heading, detail):
    print(f'{bold(heading)}: {detail}')


def test_equal(a, b, rel_tol=0.0, abs_tol=0.0):
    if a is None or b is None:
        return a is None and b is None
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) == type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        if math.isnan(a) or math.isnan(b):
            return math.isnan(a) and math.isnan(b)
        return a == b
    if isinstance(a, EventKind) and isinstance(b, EventKind):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(test_equal(a[k], b[k], rel_tol, abs_tol) for k in a)
    if isinstance(a, Spacecraft) and isinstance(b, Spacecraft):
        return test_equal(a.__dict__, b.__dict__, rel_tol, abs_tol)
    if isinstance(a, MissionEvent) and isinstance(b, MissionEvent):
        return test_equal(a.__dict__, b.__dict__, rel_tol, abs_tol)
    if isinstance(a, Vector3D) and isinstance(b, Vector3D):
        return math.isclose(a._x, b._x, rel_tol=rel_tol, abs_tol=abs_tol) and math.isclose(a._y, b._y, rel_tol=rel_tol, abs_tol=abs_tol) and math.isclose(a._z, b._z, rel_tol=rel_tol, abs_tol=abs_tol)
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(test_equal(a0, b0, rel_tol, abs_tol) for a0, b0 in zip(a, b))
    if isinstance(a, tuple) and isinstance(b, tuple):
        if len(a) != len(b):
            return False
        return all(test_equal(a0, b0, rel_tol, abs_tol) for a0, b0 in zip(a, b))
    if type(a) != type(b):
        return False
    return a == b


def announce(spacecraft, mission_elapsed_time, ephemeris_time, mission_event):
    pass

    
def show_failed_test(setup, function, args):
    print('\u274C Test Failed:')
    print()     
    if setup:
        for input in setup.split(';'):
            print(input.replace(':', ' = '))
    print(f'{function.__name__}({args.rstrip(",")})')
    print()    
    

def print_numbered(src):
    for i, line in enumerate(src.splitlines(), 1):
        print(f"{i:4}: {line}")

    
def get_tolerance(function_name):
    if function_name in ['gravitational_acceleration', 'earth_gravitational_acceleration', 'moon_gravitational_acceleration', 'drag_acceleration', 'gravity_turn_direction', 'engine_acceleration', 'net_acceleration', 'update_position_and_velocity']:
        return (1e-12, 1e-10)
    elif function_name == 'execute_mission':
        return (1e-6, 1e-3)
    else:
        return (0.0, 0.0)  


def run_tests(function, explain=True, relies_on = []):
      
    if explain:
        hr()
    
    _globals = { }
    _locals = {}

    relies_on.append(function)

    for other_function in relies_on:
        _globals[other_function.__name__] = FunctionType(other_function.__code__, _globals, name=other_function.__name__, argdefs= other_function.__defaults__, closure= other_function.__closure__)  
    
    _globals['math'] = math 
    _globals['Spacecraft'] = Spacecraft
    _globals['mission_event'] = mission_event    
    _globals['MissionEvent'] = MissionEvent
    _globals['EventKind'] = EventKind 
    _globals['announce'] = announce        
    _globals['convert_to_seconds'] = convert_to_seconds   
    _globals['convert_seconds_to_string'] = convert_seconds_to_string   
    _globals['Vector3D'] = Vector3D
    _globals['vector3d'] = vector3d    
    _globals['vector_magnitude'] = vector_magnitude
    _globals['vector_subtract'] = vector_subtract 
    _globals['vector_add'] = vector_add
    _globals['vector_scale'] = vector_scale
    _globals['zero_vector'] = zero_vector
    _globals['unit_vector'] = unit_vector     
    _globals['earth'] = earth 
    _globals['moon'] = moon    
    _globals['spice_api'] = spice_api     
    _globals['moon_position'] = moon_position   
    _globals['utc_to_ephemeris_time'] = utc_to_ephemeris_time
    _globals['ephemeris_time_to_utc_string'] = ephemeris_time_to_utc_string
    _globals['atmosphere_rotation_velocity'] = atmosphere_rotation_velocity
    _globals['earth_position_and_velocity'] = earth_position_and_velocity
    _globals['air_density'] = air_density

    if explain:
        print()
    count = 0

    if function.__name__ in tests:
        (rel_tol, abs_tol) = get_tolerance(function.__name__)
        
        for entry in tests[function.__name__]:
            dont_report = count < 2  and function.__name__ not in ['execute_mission', 'detect_perigee_and_apogee']
            
            setup, args_str, expected_result = entry[:3]
            expected_changes = entry[3] if len(entry) > 3 else None
                
            if setup:
                src = setup.replace(':', ' = ')
                try:
                    code = compile(src, "generated_setup_code.py", "exec")
                    exec(code, _globals, _locals)
                except Exception as e:
                    print("INTERNAL ERROR in test setup")
                    print_numbered(src)
                    print(f"{type(e).__name__}: {e}")
                    return False
                    
            try:
                expected_value = eval(expected_result, _globals, _locals)
                actual_result = eval(f'{function.__name__}({args_str})', _globals, _locals)
            except Exception as e:
                if explain:
                    if dont_report:
                        print(f'\u274C Test {count+1} above failed.')
                    else:
                        show_failed_test(setup, function, args_str)
                        print('Crashed with runtime exception:')
                        traceback.print_exc()
                        print(e)
                return False
    
            if not test_equal(actual_result, expected_value, rel_tol, abs_tol):
                if explain:
                    if dont_report:
                        print(f'\u274C Test {count+1} above failed.')
                    else:                    
                        show_failed_test(setup, function, args_str)
                        if isinstance(expected_value, list) and len(expected_value) > 1:
                            print('Expected result:')
                            display(expected_value)
                            print('Actual result:')
                            display(actual_result)
                        else:
                            print(f'Expected result: {expected_result}')
                            print(f'Actual   result: {actual_result}')
                return False
            
            if expected_changes:                   
                for part in expected_changes.split(';'):      
                    name, expect = part.split(':', 1)
                    actual = eval(name, _globals, _locals)
                    expected = eval(expect, _globals, _locals)
                    if not test_equal(actual, expected, rel_tol, abs_tol):
                        if explain:
                            if dont_report:
                                print(f'\u274C Test {count+1} above failed.')
                            else:                                 
                                show_failed_test(setup, function, args_str)
                                if isinstance(expected, list) and len(expected) > 1:
                                    print(f'{name} is expected to be:')
                                    display(expected)
                                    print(f'But {name} is actually:')
                                    display(actual)
                                else:
                                    print(f'{name} is expected to be: {expected}')
                                    print(f'But {name} is actually  : {actual}')
                        return False
            else:
                if setup:
                    for item in setup.split(';'): 
                        lhs, rhs = item.split(':', 1)
                        expected = eval(rhs, _globals, _locals)
                        actual = eval(lhs, _globals, _locals)
                        if not test_equal(actual, expected, 0, 0):
                            if explain:
                                show_failed_test(setup, function, args_str)
                                print(f'Input parameter {lhs} should not be modified')
                                if isinstance(expected, list) and len(expected) > 1:
                                    print(f'It should remain as:')
                                    display(expected)
                                    print(f'But has changed to:')
                                    display(actual)
                                else:
                                    print(f'It should remain as: {expected}')
                                    print(f'But has changed to : {actual}')
                            return False                                                     
            count += 1

    if explain:
        if count > 0:
            print(f'\u2705 {function.__name__} Passed all ({count}) tests, well done!')
        else:
            print(f'\u274C {function.__name__} No tests exist for this function all ???')
    return True


